package mdxrender

import (
	"encoding/json"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

// The goldens are generated by the TypeScript renderer; see
// testdata/generate.mjs for how to regenerate them:
//
//	pnpm build:cli && node cli/internal/mdx/testdata/generate.mjs

type golden struct {
	HTML     string   `json:"html"`
	Problems []string `json:"problems"`
}

var betweenTags = regexp.MustCompile(`>[ \t\r\n]+<`)

// normalize drops whitespace-only text between tags, the one place goldmark
// and react-markdown are allowed to differ.
func normalize(html string) string { return betweenTags.ReplaceAllString(html, "><") }

func compareGolden(t *testing.T, source string, want golden) {
	t.Helper()
	html, problems := render(source)
	if problems == nil {
		problems = []string{}
	}
	if strings.Join(problems, "\n") != strings.Join(want.Problems, "\n") {
		t.Errorf("source %q\nproblems\n got: %q\nwant: %q", source, problems, want.Problems)
	}
	if normalize(html) != normalize(want.HTML) {
		t.Errorf("source %q\nhtml\n got: %s\nwant: %s", source, html, want.HTML)
	}
}

func readJSON(t *testing.T, path string, v any) {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, v); err != nil {
		t.Fatal(err)
	}
}

func TestGoldenCases(t *testing.T) {
	var sources []string
	var want []golden
	readJSON(t, "testdata/cases.json", &sources)
	readJSON(t, "testdata/golden/cases.json", &want)
	if len(sources) != len(want) {
		t.Fatalf("%d cases but %d goldens; regenerate the goldens", len(sources), len(want))
	}
	for i, source := range sources {
		compareGolden(t, source, want[i])
	}
}

func TestBlocksCatalogMatchesTypeScript(t *testing.T) {
	wantJSON, err := os.ReadFile("testdata/blocks.json")
	if err != nil {
		t.Fatal(err)
	}
	got, err := CatalogJSON()
	if err != nil {
		t.Fatal(err)
	}
	if string(got)+"\n" != string(wantJSON) {
		t.Errorf("blocks --json\n got: %s\nwant: %s", got, wantJSON)
	}
	wantText, err := os.ReadFile("testdata/blocks.md")
	if err != nil {
		t.Fatal(err)
	}
	if BlocksReference() != string(wantText) {
		t.Errorf("blocks reference differs\n got: %s\nwant: %s", BlocksReference(), wantText)
	}
}

func TestGoldenCorpus(t *testing.T) {
	files, err := filepath.Glob("testdata/corpus/*.mdx")
	if err != nil || len(files) == 0 {
		t.Fatalf("no corpus: %v", err)
	}
	for _, file := range files {
		name := strings.TrimSuffix(filepath.Base(file), ".mdx")
		t.Run(name, func(t *testing.T) {
			source, err := os.ReadFile(file)
			if err != nil {
				t.Fatal(err)
			}
			var want golden
			readJSON(t, filepath.Join("testdata", "golden", name+".json"), &want)
			compareGolden(t, string(source), want)
		})
	}
}
